import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.variations().listProductVariations(4321);
for (Object group : (List<?>) ((Map<?, ?>) response.getMap()).get("variations")) {
    System.out.println(((Map<?, ?>) group).get("product_key"));
    for (Object row : (List<?>) ((Map<?, ?>) group).get("variants")) {
        Map<?, ?> variant = (Map<?, ?>) row;
        Map<?, ?> pricing = (Map<?, ?>) variant.get("pricing");
        Map<?, ?> inventory = (Map<?, ?>) variant.get("inventory");
        System.out.println(variant.get("variation_id") + " " + variant.get("key") + " "
                + pricing.get("base_price") + " " + inventory.get("quantity"));
    }
}

